</div>
<script>
const state={{time:0}};
const canvas=document.getElementById('{name}-canvas');
const draw=()=>window.PaperFilm.draw(canvas,state.time+{offset});
const tl=gsap.timeline({{paused:true}});
tl.fromTo(state,{{time:0}},{{time:15,duration:15,ease:'none',onUpdate:draw}},0);
draw();
window.__timelines=window.__timelines||{{}};
window.__timelines['{name}']=tl;
</script></template>''')
